	// columnTypeSpec converts from a concrete MySQL schema.Type into sqlspec.Column Type.
	func columnTypeSpec(t schema.Type) (*sqlspec.Column, error) {
		st, err := TypeRegistry.Convert(t)
		if err != nil {
			return nil, err
		}
		c := &sqlspec.Column{Type: st}

		// Find the TypeSpec for this type to determine which attributes are core vs extra
		typeSpec, ok := TypeRegistry.FindT(st.T)
		if !ok {
			// If we can't find the TypeSpec, treat all attributes as extra
			c.Extra.Attrs = append(c.Extra.Attrs, st.Attrs...)
			return c, nil
		}

		// Create a map of core attribute names for quick lookup
		coreAttrNames := make(map[string]bool)
		for _, attr := range typeSpec.Attributes {
			coreAttrNames[attr.Name] = true
		}

		// Separate attributes into core and extra
		var coreAttrs []*schemahcl.Attr
		for _, attr := range st.Attrs {
			if coreAttrNames[attr.K] {
				coreAttrs = append(coreAttrs, attr)
			} else {
				c.Extra.Attrs = append(c.Extra.Attrs, attr)
			}
		}

		// Update the spec type to only include core attributes
		st.Attrs = coreAttrs

		return c, nil
	}
